<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,messageOf} from '@/lib/api';const rows=ref<any[]>([]),form=ref({legal_name:'',trade_name:'',tax_id:'',state_registration:''}),error=ref('');async function load(){rows.value=(await api.get('/companies',{params:{per_page:100}})).data.data}onMounted(load);async function save(){try{await api.post('/companies',form.value);form.value={legal_name:'',trade_name:'',tax_id:'',state_registration:''};await load()}catch(e){error.value=messageOf(e)}}</script><template><div class="split"><section class="card"><h2>Empresas</h2><table><thead><tr><th>Razão social</th><th>Fantasia</th><th>CNPJ/CPF</th><th>Ativa</th></tr></thead><tbody><tr v-for="c in rows"><td>{{c.legal_name}}</td><td>{{c.trade_name}}</td><td>{{c.tax_id}}</td><td>{{c.active?'Sim':'Não'}}</td></tr></tbody></table></section><form class="card form-grid one" @submit.prevent="save"><h2>Nova empresa</h2><label>Razão social<input v-model="form.legal_name" required/></label><label>Nome fantasia<input v-model="form.trade_name"/></label><label>CNPJ/CPF<input v-model="form.tax_id" required/></label><label>Inscrição estadual<input v-model="form.state_registration"/></label><p class="error" v-if="error">{{error}}</p><button class="primary">Cadastrar</button></form></div></template>
